function spotifySection(){if(!spotifyUrl)return '<p class="meta">Playlist coming soon.</p>';const url=new URL(spotifyUrl);const match=url.pathname.match(/^\/(playlist|album|track)\/([A-Za-z0-9]+)$/);if(url.hostname!=='open.spotify.com'||!match)return '';return `<iframe title="Stephanie’s Spotify playlist" src="https://open.spotify.com/embed/${match[1]}/${match[2]}" width="100%" height="352" style="border:0;border-radius:12px" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe><p><a href="${url.href}" target="_blank" rel="noopener">Listen on Spotify ↗</a></p>`}
