const projectSummaries={"matcha": "An acquired app that turns handwritten notes into study tools.", "marketplace": "A student marketplace for life across international rotations.", "evoluer": "A fragrance concept that evolves with the seasons.", "bulby": "A desktop meeting copilot with live transcription and screenshot context.", "beacon": "A tsunami disaster app.", "cyber": "Teaching command-line skills through capture-the-flag challenges.", "vectorizer": "Turn images and videos into grayscale matrices.", "nfa": "Explore nondeterministic automata through interactive computation trees.", "preclass": "Prepare course readings for a study session in ChatGPT.", "mymizu": "A refill-map prototype for building sustainable hydration habits.", "green-carbon": "A field-mapping and farmer-logbook prototype.", "yuki-issei": "A music, website, and branding project with UTAITE.", "instagram": "Compare Instagram followers and following locally.", "setlist": "Track workouts and export your gym log.", "homework-hound": "A pixel dog that makes it look like your homework was eaten."};
const expandedDescriptions={"aura-protection":"Aura Protection is a concept for making attention boundaries visible instead of burying them in settings. The interaction centers on a small, playful pause before a distracting action. The interesting product challenge is designing an interruption that feels helpful without becoming another distraction.","beacon":"Beacon is an academic concept for tsunami preparedness and response. It organizes hazard information into a short sequence of actions so a person can find the next step under time pressure. The technical design challenge is prioritizing location, alert state, and offline access without making the emergency interface harder to scan.","bffr":"BFFR is a digital reality-check concept with a deliberately direct voice. It turns a moment of overthinking into a short prompt to reconsider an assumption. The design experiment is how much personality an interface can have while still giving people a clear, useful interaction.","bulby":"Bulby is an Electron desktop overlay that transcribes microphone and call audio locally with faster-whisper. I connected the live transcript and a fresh screenshot to a Chrome extension that hands context to ChatGPT only when the user asks. The compact window can expand, move, and resize; the local transcription path needs no OpenAI API key.","caba":"Caba is an academic product concept for simplifying a complicated workflow. The proposed interface breaks information into smaller decisions and makes progress visible. Its technical focus is information architecture: deciding what the tool needs to store, what the user must enter, and what can be deferred.","caughtcha":"Caughtcha is a small JavaScript experiment about noticing online habits in the moment. It uses a well-timed interruption as the central interaction rather than a dashboard of retrospective statistics. The interesting design constraint is making the prompt noticeable without making it disruptive.","christmas-lights":"Christmas Lights is an interactive seasonal screen experiment built in JavaScript. Instead of a static holiday image, it treats light and motion as the interface. The project is a small study in timing, visual feedback, and making a browser feel like an object in a room.","cyber":"Cyber for Students taught command-line and networking fundamentals across 16 countries. I provisioned dedicated Linux virtual machines so learners could practice in their own environments. The curriculum used 250 custom capture-the-flag challenges, turning shell and security concepts into problems students could solve hands-on.","delusiongpt":"DelusionGPT is a TypeScript command-line companion for stressed developers. It uses Commander and Inquirer for the terminal flow and Chalk for its intentionally theatrical responses. The interesting constraint is expressing a distinct personality through text, prompts, and timing instead of a graphical interface.","evoluer":"ÉVOLUER is a L’Oréal Brandstorm fragrance concept built around one base scent that changes through the seasons. We designed a spray-count mechanism for releasing monthly scent capsules and mapped the experience from bottle use to an in-store Fragrance Observatory. The work combined product mechanics, scent-journey prototyping, and brand design; it won the Japan national round in 2026.","green-carbon":"Green Carbon is a working field-mapping and farmer-logbook prototype. It uses Leaflet for polygon drawing and overlap checks, Supabase for profile and field data, and local storage as a fallback when the service is unavailable. The workflow links boundary geometry to activity records so farm verification is easier to inspect, including in low-connectivity settings.","homework-hound":"Homework Hound is a Chrome extension that sends a pixel dog across the current page to “eat” the homework. JavaScript controls the dog’s appetite, the page effect, stopping, and cleanup so the interaction is reversible. It can also export an evidence.png screenshot of the joke.","instagram":"Instagram Follow Checker compares followers and following from Instagram exports entirely in the browser. It reads multiple ZIPs or extracted JSON/HTML, combines numbered follower files, and deduplicates usernames before showing searchable results. The ZIP parser handles stored and deflated entries, including ZIP64, without an account, server upload, or installation.","lockin-twin":"Lockin Twin is a focus-companion app built with React and TypeScript. Its repository uses MediaPipe Face Mesh for camera-based face tracking and Framer Motion for interface animation. The technical experiment is whether a responsive character can make the start of a work session feel less solitary.","matcha":"Matcha turned handwritten notes into AI flashcards and practice tests for active recall. As CPO, I led product decisions, branding, and growth while shaping the note-to-study workflow. It reached 320 active users in its first month and was acquired for integration into a productivity-app suite.","marketplace":"Minerva Marketplace is a peer-to-peer marketplace designed for a student community of about 1,000 across international rotations; that is the target community, not a claimed active-user count. I designed PostgreSQL schemas for users and listings, implemented OAuth, and set up scheduled email notifications. The interesting systems problem is keeping listings and transactions useful as students change cities each semester.","mymizu":"Mymizu is a React prototype for making water refills easier to find and repeat. The consumer side combines a Google Maps refill map, daily refill tracking, and a growing sprout companion; an admin view diagnoses underserved “red zones” and suggests new stations. I explored how geospatial analysis, reminders, and small rewards can connect individual behavior to network coverage.","nfa":"NFA Tree Lab is an interactive automata visualizer written in JavaScript. It traces a binary string one symbol at a time, shows every active state, and expands the full nondeterministic computation tree. Explicit epsilon transitions and image export make a usually abstract formal-language concept inspectable and shareable.","preclass":"Preclass is a Manifest V3 Chrome and Edge extension for Minerva Forum readings. It collects instructions, links, and questions into a reviewable prompt, then sends that prompt to a chosen ChatGPT course conversation. The handoff preserves existing drafts and offers a copy fallback, with no backend, API key, analytics, or inference billing.","seen":"seen. is a TypeScript and Next.js experiment built around the feeling of being left on read. Its repository includes React, an OpenRouter integration, and scripts for iMessage interaction. The interesting technical question is how to turn a familiar messaging signal into a responsive experience rather than a static joke.","setlist":"Setlist is a weekly workout log that keeps exercise entries in the browser. It records visit times, calculates total duration, and exports a CSV for spreadsheet analysis. The useful engineering detail is keeping the everyday workflow quick while making the data portable.","speakeasy-terminal":"Speakeasy Terminal is a concept for a hidden space navigated through typed commands. It treats command parsing, discoverability, and feedback as the experience rather than hiding them behind conventional menus. The design challenge is making a terminal feel inviting to someone who has never used one.","twin":"Twin is a concept for a digital counterpart shaped by a person’s preferences and repeated interactions. It explores what the interface would need to remember to feel consistent over time. The technical product question is how to make that state legible and editable, so personalization stays understandable.","vectorizer":"Vectorizer converts images and video frames into 50 × 50 grayscale matrices for a linear-algebra exploration. A Python CLI can export CSV, JSON, or Sage-compatible matrix text, while a Flask app processes uploaded images and clips. I varied epsilon thresholds and replayed processed frames to inspect information loss and motion continuity.","yuki-issei":"Yuki Issei combined a musician’s web presence, visual identity, and short-form content. I built the site, edited clips and a lyric video, designed the poster, and coordinated the production workflow. AI-assisted song drafts became a starting point for human vocal recordings with the singer."};
const projectSkills={"aura-protection":"Product concept · Interaction design · Attention UX","beacon":"Emergency UX · Information architecture · Offline-first design","bffr":"Product concept · Conversational UX · Voice design","bulby":"Electron · TypeScript · faster-whisper · Chrome extension","caba":"Information architecture · Workflow design · Prototyping","caughtcha":"JavaScript · Interaction design · Behavioral UX","christmas-lights":"JavaScript · Motion design · Creative coding","cyber":"Linux VMs · CLI · Networking · CTF design","delusiongpt":"TypeScript · Node.js · Commander · Inquirer","evoluer":"Product mechanics · Prototyping · Brand design","green-carbon":"Leaflet · Supabase · Geospatial data · Offline fallback","homework-hound":"JavaScript · Chrome extension · DOM interaction","instagram":"Client-side ZIP parsing · JSON/HTML · Search UI","lockin-twin":"React · TypeScript · MediaPipe Face Mesh · Framer Motion","matcha":"AI study tools · Product strategy · Growth","marketplace":"PostgreSQL · OAuth · Scheduled email","mymizu":"React · Google Maps · Geospatial analysis · Behavioral design","nfa":"JavaScript · Automata · Computation trees","preclass":"JavaScript · Manifest V3 · Browser automation","seen":"Next.js · TypeScript · React · OpenRouter","setlist":"Browser storage · Duration calculation · CSV export","speakeasy-terminal":"Command UX · Interaction design · Information architecture","twin":"Personalization · State design · Product concept","vectorizer":"Python · Flask · Image processing · Linear algebra","yuki-issei":"Web development · Video editing · Creative production"};
const draftDescriptions=new Set(["aura-protection", "beacon", "bffr", "caba", "caughtcha", "christmas-lights", "delusiongpt", "lockin-twin", "seen", "speakeasy-terminal", "twin"]);
const projectRepos={"aura-protection": "https://github.com/stephyg0/aura-protection", "bffr": "https://github.com/stephyg0/bffr", "caughtcha": "https://github.com/stephyg0/caughtcha", "delusiongpt": "https://github.com/stephyg0/delusiongpt", "green-carbon": "https://github.com/stephyg0/greencarbon-extension", "homework-hound": "https://github.com/stephyg0/homework-dog", "instagram": "https://github.com/stephyg0/instagram-follow-checker", "bulby": "https://github.com/stephyg0/local-meeting-copilot", "lockin-twin": "https://github.com/stephyg0/lock-in-twin", "mymizu": "https://github.com/stephyg0/mymizu-extension", "nfa": "https://github.com/stephyg0/nfa-tree-lab", "preclass": "https://github.com/stephyg0/preclass", "seen": "https://github.com/stephyg0/seen.", "setlist": "https://github.com/stephyg0/setlist-gym-log", "vectorizer": "https://github.com/stephyg0/vectorizer"};
const allProjects=[...computerGroups.flatMap(g=>g.apps.map(([name,id])=>({...projectEntries.find(p=>p.id===id),id,name,group:g.title}))),...projectEntries.filter(p=>!computerGroups.some(g=>g.apps.some(([,id])=>id===p.id))).map(p=>({...p,name:p.title,group:'Other'}))].filter(p=>!excludedProjectIds.has(p.id)).map(p=>({...p,repository:projectRepos[p.id]||null,description:expandedDescriptions[p.id]||p.description,provisional:draftDescriptions.has(p.id)})).sort((a,b)=>a.name.localeCompare(b.name,'en',{sensitivity:'base'}));
function filterProjects(group){main.querySelectorAll('[data-project-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.projectFilter===group)));main.querySelectorAll('[data-project-group]').forEach(p=>p.hidden=group!=='All'&&p.dataset.projectGroup!==group)}
main.addEventListener('click',e=>{const b=e.target.closest('[data-project-filter]');if(b)filterProjects(b.dataset.projectFilter)});

const romcoms=["10 Things I Hate About You", "Notting Hill", "Confessions of a Shopaholic", "How to Lose a Guy in 10 Days", "27 Dresses", "A Cinderella Story", "Drive Me Crazy"];
let romcomChannel=0;
main.addEventListener('click',e=>{const button=e.target.closest('[data-tv]');if(!button||!romcoms.length)return;romcomChannel=Number(main.querySelector('.tv-screen').dataset.channel||0);romcomChannel=(romcomChannel+(button.dataset.tv==='next'?1:-1)+romcoms.length)%romcoms.length;const screen=main.querySelector('.tv-screen');screen.dataset.channel=String(romcomChannel);screen.querySelector('.tv-channel').textContent='CH '+String(romcomChannel+1).padStart(2,'0');screen.querySelector('.tv-title').textContent=romcoms[romcomChannel];screen.querySelector('.tv-caption').textContent='one of my favourites';});
// Add the owner's selected artwork here; no stock art is presented as hers.
const galleryArt=[];
function gallerySection(){return `<section class="little-gallery" aria-label="Art gallery"><h2>Art gallery</h2>${galleryArt.length?`<div class="gallery-wall">${galleryArt.map((art,i)=>`<button class="gallery-frame" data-art="${i}" aria-label="View ${art.title}"><img src="${art.src}" alt="${art.title}" loading="lazy"><span>${art.title}</span></button>`).join('')}</div>`:'<p class="gallery-empty">Empty for now.</p>'}</section>`}
main.addEventListener('click',e=>{const button=e.target.closest('[data-art]');if(!button)return;const art=galleryArt[Number(button.dataset.art)];if(!art)return;const dialog=document.createElement('dialog');dialog.className='gallery-view';dialog.setAttribute('aria-label',art.title);const close=document.createElement('button');close.type='button';close.textContent='Close ×';const img=document.createElement('img');img.src=art.src;img.alt=art.title;const caption=document.createElement('p');caption.textContent=art.title;dialog.append(close,img,caption);document.body.append(dialog);close.addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.remove();button.focus()});dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});dialog.showModal();close.focus()});
const pages={
home:()=>`<h1>Stephanie Gao</h1><p>Hi, I’m Steph. I study computer science and cognitive science at Minerva University.</p><p>I build tools that make tech feel a little more whimsical. I worked in product and growth at Dedalus Labs. Before that, I was CPO of my app Matcha, which got acquired, and a technical project manager at Axlora, a compliance company acquired by Cognition.</p><p>Outside of that: dance, hiking, makeup, content creation, and rom-coms.</p><h2>A few things I’ve worked on</h2><ul><li><a href="#projects/matcha">Matcha</a>: my AI study app, acquired.</li><li><a href="#projects/marketplace">Minerva Marketplace</a>: a peer-to-peer marketplace for students across international rotations.</li><li><a href="#projects/bulby">Bulby</a>: a desktop meeting copilot with local transcription and screenshot context.</li></ul><p class="quiet">More about my <a href="#experiences">experience</a>, <a href="#places">places I’ve called home</a>, <a href="#blog">writing</a>, and <a href="#hobbies">things I do outside work</a>.</p>`,
projects:()=>`<h1>Projects</h1><div class="project-filters" role="group" aria-label="Project categories">${['My favourites','Academic','Content apps','Other','All'].map((name,i)=>`<button data-project-filter="${name}" aria-pressed="${i===0}">${name}<sup>${name==='All'?allProjects.length:allProjects.filter(p=>p.group===name).length}</sup></button>`).join('')}</div><div class="project-board">${allProjects.map(p=>`<article id="project-${p.id}" data-project-group="${p.group}" ${p.group!=='My favourites'?'hidden':''}><details name="projects"><summary><span class="project-heading"><span>${p.name}</span><span class="project-teaser">${projectSummaries[p.id]||'A personal project. More details coming soon.'}</span></span><span class="project-plus" aria-hidden="true">+</span></summary><div class="project-description">${draftDescriptions.has(p.id)?'<span class="meta">Provisional description</span>':''}<p>${p.description||'More about this project coming soon.'}</p><p class="project-skills"><strong>Relevant skills:</strong> ${projectSkills[p.id]||p.tags||'Details coming soon.'}</p>${p.repository?`<p><a href="${p.repository}" target="_blank" rel="noopener">GitHub ↗</a></p>`:''}</div></details></article>`).join('')}</div>`,
experiences:()=>`<h1>Experiences</h1><p><a href="https://www.linkedin.com/in/stephaniesgao" target="_blank" rel="noopener">LinkedIn</a> · <a href="Stephanie-Gao-Resume.pdf?v=3" target="_blank" rel="noopener">Résumé ↗</a></p><div class="resume-layout"><h2>Education</h2><article class="resume-entry"><div class="resume-row"><h3>Minerva University</h3><span>Expected May 2028</span></div><div class="resume-row resume-role"><span>Bachelor of Arts, Computer Science & Cognitive Science</span><span>San Francisco, CA</span></div><ul><li>GPA: 3.83/4.0</li><li>Relevant Coursework: Single and Multivariate Calculus, Linear Algebra, Data Structures and Algorithms, Complex Systems, Formal Analysis</li></ul></article><article class="resume-entry"><div class="resume-row"><h3>Pearson College UWC</h3><span>Aug 2022 – May 2024</span></div><div class="resume-row resume-role"><span>International Baccalaureate</span><span>Victoria, BC</span></div></article><h2>Experiences</h2><article class="resume-entry"><div class="resume-row"><h3>Dedalus Labs (YC S25)</h3><span>Jun 2026 – Aug 2026</span></div><div class="resume-row resume-role"><span>Technical Product & Growth Intern</span><span>San Francisco, CA</span></div><ul><li>Built CLI authentication system with self-hosted auth server and service accounts for API key provisioning.</li><li>Redesigned onboarding around in-browser terminals, set up 46 tracked events to identify activation drop-offs.</li><li>Organized and hosted a YC Startup School event that generated a 1,100+ person waitlist.</li></ul></article><article class="resume-entry"><div class="resume-row"><h3>Matcha</h3><span>November 2025 – March 2026</span></div><div class="resume-row resume-role"><span>Chief Product Officer</span><span>San Francisco, CA</span></div><ul><li>Acquired by productivity apps company to integrate into its suite of study tools.</li><li>Developed a digital notebook turning handwritten notes into AI flashcards and practice tests for active recall.</li><li>Led product, branding, and growth initiatives that brought the product to 320 active users in its first month.</li></ul></article><article class="resume-entry"><div class="resume-row"><h3>Axlora</h3><span>May 2025 – Aug 2025</span></div><div class="resume-row resume-role"><span>Technical Project Management Intern</span><span>San Francisco, CA</span></div><ul><li>Managed SOC 2 and GDPR compliance projects for 20+ enterprise customers with zero audit exceptions.</li><li>Built an internal application tracking 1,400 control tests, giving teams a single view of upcoming requirements.</li><li>Owned Axlora’s visual brand end-to-end, creating its brand kit, website, and all customer-facing assets.</li></ul></article><article class="resume-entry"><div class="resume-row"><h3>TELUS Spark Science</h3><span>Jun 2023 – Aug 2024</span></div><div class="resume-row resume-role"><span>Robot Operator & Science Guide</span><span>Calgary, AB</span></div><ul><li>Led 100+ hours of chemistry lab demos for 150+ daily visitors, delivering hands-on science experiences.</li><li>Operated Boston Dynamics’ Spot robot and Unitree’s quadruped robot as the center’s first trained operator.</li><li>Built a sensor-reactive robot fetch feature and interactive Scratch program to teach coding to children of all ages.</li></ul></article></div>`,
blog:()=>`<h1>Writing</h1><p>Personal reflections and notes from my reading.</p><ul class="writing-list">${posts.map(p=>`<li><a href="#blog/${p.id}">${p.title}</a><span class="meta">${p.date}</span></li>`).join('')}</ul>`,
places:()=>`<h1>Places</h1><p>A few chapters from Canada, the Bay Area, Tokyo, and Buenos Aires.</p><div class="postcard-grid"><article class="place-postcard"><div class="postcard-picture"><img src="photos/pearson.jpg" alt="Pearson College campus" loading="lazy"><span>Canada</span></div><div class="postcard-note"><span class="postcard-stamp" aria-hidden="true"><img src="objects/stamp-canada.svg" alt=""></span><h2>Dear Canada,</h2><p>Pearson College, backcountry trails, and weekends building boardwalks to protect old-growth forests.</p><span class="postcard-sign">with love, Steph</span></div></article><article class="place-postcard"><div class="postcard-picture"><img src="photos/redwoods.jpg" alt="Sunlight through redwoods above a forest trail" loading="lazy"><span>Bay Area</span></div><div class="postcard-note"><span class="postcard-stamp" aria-hidden="true"><img src="objects/stamp-bay.svg?v=2" alt=""></span><h2>From the Bay,</h2><p>My first-year Minerva chapter. During fall break, I brought friends to Muir Woods to reconnect with the outdoors.</p><a href="#blog/woods">Muir Woods, fall 2024 ↗</a><span class="postcard-sign">with love, Steph</span></div></article><article class="place-postcard"><div class="postcard-picture"><img src="photos/tokyo.jpg" alt="Tokyo city scene" loading="lazy"><span>Tokyo</span></div><div class="postcard-note"><span class="postcard-stamp" aria-hidden="true"><img src="objects/stamp-tokyo.svg" alt=""></span><h2>Hello from Tokyo,</h2><p>Another Minerva chapter, in spring 2026.</p><span class="postcard-sign">with love, Steph</span></div></article><article class="place-postcard"><div class="postcard-picture postcard-lettering"><small>greetings from</small><span>Buenos<br>Aires</span><small>Argentina · here, now</small></div><div class="postcard-note"><span class="postcard-stamp" aria-hidden="true"><img src="objects/stamp-buenos-aires.svg" alt=""></span><h2>Writing from here,</h2><p>Where I’m currently based.</p><span class="postcard-sign">with love, Steph</span></div></article></div>`,
hobbies:()=>`<div class="after-hours"><header class="after-heading"><span class="after-eyebrow">STEPH'S PERSONAL INDEX / VOL. 01</span><h1>Outside of work<span class="after-stop">.</span></h1></header>
<div class="after-viewer" aria-label="Outside of work interactive index"><div class="after-rule"><span>AFTER HOURS</span><span class="after-count">01 / 06</span></div><div class="after-scenes">
<article class="after-scene is-active" data-after-scene="0"><div class="after-object after-camera"><button class="camera-open" aria-label="Open my camera roll"><img src="objects/camera-photo.png" alt="" aria-hidden="true"></button><span class="object-shadow"></span></div><div class="after-copy"><span class="after-index">01 / CAMERA ROLL</span><h2>Making content</h2><p>Short videos, makeup, and little moments I want to keep.</p><button class="after-link camera-open">Open camera roll ↗</button></div></article>
<article class="after-scene" data-after-scene="1" hidden><div class="after-object after-record"><div class="mini-turntable"><div class="turntable-deck"><span class="vinyl" aria-hidden="true"></span><button type="button" class="tonearm" aria-label="Drop needle" aria-pressed="false"><img src="objects/record-tonearm-photo.png" alt=""></button><button type="button" class="record-skip" aria-label="Open Spotify track controls">▸▸</button></div><p class="record-message" role="status">Drop the needle to play.</p></div></div><div class="after-copy"><span class="after-index">02 / SOUNDTRACK</span><h2>On repeat</h2><p>My playlist, on a record player you can actually use.</p><button class="after-link record-skip">Open the playlist ↗</button></div></article>
<article class="after-scene" data-after-scene="2" hidden><div class="after-object after-tv"><div class="tiny-tv"><div class="tv-shell"><div class="tv-screen" aria-live="polite"><span class="tv-channel">CH 01</span><strong class="tv-title">10 Things I Hate About You</strong><span class="tv-caption" hidden>one of my favourites</span></div><div class="tv-controls"><button type="button" data-tv="previous" aria-label="Previous movie">−</button><button type="button" data-tv="next" aria-label="Next movie">+</button></div></div></div></div><div class="after-copy"><span class="after-index">03 / STEPH TV</span><h2>Rom-com channel</h2><p>Seven favourites. Use the little buttons to change the channel.</p></div></article>
<article class="after-scene" data-after-scene="3" hidden><div class="after-object after-dance"><button class="dance-open" aria-label="Open dance breaks"><span class="music-box"><img class="music-box-drawing" src="objects/musicbox-photo.png" alt="" aria-hidden="true"><span class="ballerina-spinner" aria-hidden="true"><span class="ballerina-face ballerina-front"></span><span class="ballerina-face ballerina-right"></span><span class="ballerina-face ballerina-back"></span><span class="ballerina-face ballerina-left"></span></span><img class="ballerina-still" src="objects/ballerina-asian-still.png" alt="" aria-hidden="true"></span></button></div><div class="after-copy"><span class="after-index">04 / INTERMISSION</span><h2>Dance breaks</h2><p>A little movement between everything else.</p><button class="after-link dance-open">Open the music box ↗</button></div></article>
<article class="after-scene" data-after-scene="4" hidden><div class="after-object after-books"><button type="button" class="books-open" aria-label="Open my books"><img class="after-books-drawing" src="objects/books-v3-photo.png" alt="" aria-hidden="true"></button></div><div class="after-copy"><span class="after-index">05 / MARGINALIA</span><h2>On the shelf</h2><p>One book to share and one on my nightstand.</p><button class="after-link books-open">Open the books ↗</button></div></article>
<article class="after-scene" data-after-scene="5" hidden><div class="after-object after-hike"><a class="hiking-boots-link" href="#blog/woods" aria-label="Read my Muir Woods note"><img src="objects/hiking-boots-photo.png" alt="A pair of brown leather hiking boots"></a></div><div class="after-copy"><span class="after-index">06 / FIELD NOTES</span><h2>Taking the long way</h2><p>Hiking, camping, and finding my way back to the trees.</p><a class="after-link" href="#blog/woods">Read the Muir Woods note ↗</a></div></article>
</div><div class="after-navigation"><span>USE THE INDEX TO LOOK AROUND</span><div><button data-after-prev aria-label="Previous interest">←</button><button data-after-next aria-label="Next interest">→</button></div></div></div>
<nav class="after-strip" aria-label="Browse interests">${[['01','content','camera-photo.png'],['02','music','record-deck-photo.png'],['03','films','tv-photo.png'],['04','dance','musicbox-photo.png'],['05','books','books-v3-photo.png'],['06','outside','hiking-boots-photo.png']].map(([number,label,asset],i)=>`<button type="button" data-after-go="${i}" aria-current="${i===0?'true':'false'}"><span class="strip-thumb"><img src="objects/${asset}" alt=""></span><span class="strip-number">${number}</span><span class="strip-label">${label}</span></button>`).join('')}</nav>${gallerySection()}</div>`
};
function render(){const [route='home',slug]=location.hash.slice(1).split('/');const key=pages[route]?route:'home';document.querySelector('.more').open=false;document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(key==='projects'&&['nfa','preclass','matcha'].includes(slug)){main.innerHTML='<p class="back"><a href="#projects">← Projects</a></p>';main.append(document.querySelector('#content-'+slug).content.cloneNode(true));if(slug==='nfa')mountTrace()}else if(key==='blog'&&posts.some(p=>p.id===slug)){const p=posts.find(p=>p.id===slug);main.innerHTML=`<article><p class="back"><a href="#blog">← Writing</a></p><h1>${p.title}</h1><p class="meta">${p.date}</p>${p.body}</article>`}else main.innerHTML=pages[key]();if(key==='projects'&&slug&&projectRepos[slug]&&['nfa','preclass','matcha'].includes(slug)){const link=document.createElement('a');link.href=projectRepos[slug];link.textContent='View on GitHub ↗';link.target='_blank';link.rel='noopener';main.append(link)}clearSearch();if(key==='projects'&&slug&&!['nfa','preclass','matcha'].includes(slug))requestAnimationFrame(()=>{filterProjects('All');const target=document.getElementById('project-'+slug);if(target){target.querySelector('details').open=true;target.scrollIntoView()}});document.title=key==='home'?'Stephanie Gao':(key==='hobbies'?'Outside of work':main.querySelector('h1').textContent)+' | Stephanie Gao';if(render.done){main.focus({preventScroll:true});window.scrollTo(0,0)}render.done=true}
function showAfterScene(index){const root=main.querySelector('.after-hours');if(!root)return;const scenes=[...root.querySelectorAll('[data-after-scene]')];const next=(index+scenes.length)%scenes.length;scenes.forEach((scene,i)=>{scene.hidden=i!==next;scene.classList.toggle('is-active',i===next)});root.querySelectorAll('[data-after-go]').forEach((button,i)=>button.setAttribute('aria-current',String(i===next)));root.querySelector('.after-count').textContent=String(next+1).padStart(2,'0')+' / 06';const scene=scenes[next];if(!matchMedia('(prefers-reduced-motion: reduce)').matches)scene.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:'cubic-bezier(.2,.8,.2,1)'});}
main.addEventListener('click',e=>{const root=e.target.closest('.after-hours');if(!root)return;const active=Number(root.querySelector('.after-scene.is-active').dataset.afterScene);const pick=e.target.closest('[data-after-go],[data-after-prev],[data-after-next]');if(!pick)return;showAfterScene(pick.hasAttribute('data-after-go')?Number(pick.dataset.afterGo):active+(pick.hasAttribute('data-after-next')?1:-1))});
main.addEventListener('keydown',e=>{if(!e.target.closest('.after-hours')||!['ArrowLeft','ArrowRight'].includes(e.key)||e.target.matches('input,textarea'))return;e.preventDefault();const root=main.querySelector('.after-hours');const active=Number(root.querySelector('.after-scene.is-active').dataset.afterScene);showAfterScene(active+(e.key==='ArrowRight'?1:-1))});
window.addEventListener('hashchange',render);document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus()});document.addEventListener('click',e=>{if(!e.target.closest('.more'))document.querySelector('.more').open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.more').open){document.querySelector('.more').open=false;document.querySelector('.more summary').focus()}});

