const patterns=['0010001110111110111000100','1111110001101011000111111','0010000100111110010000100','1000111011101011000110001'];
function clues(line){return line.join('').split(/0+/).filter(Boolean).map(v=>v.length).join(' ')||'0'}
function flip(i){const r=Math.floor(i/gridSize),c=i%gridSize;for(const [dr,dc] of [[0,0],[-1,0],[1,0],[0,-1],[0,1]]){const y=r+dr,x=c+dc;if(y>=0&&y<gridSize&&x>=0&&x<gridSize)board[y*gridSize+x]=!board[y*gridSize+x]}}
function scoreWord(word,target){const result=Array(5).fill('absent'),left=target.split('');for(let i=0;i<5;i++)if(word[i]===left[i]){result[i]='correct';left[i]=null}for(let i=0;i<5;i++)if(result[i]!=='correct'){const j=left.indexOf(word[i]);if(j!==-1){result[i]='present';left[j]=null}}return result}
function paintPuzzle(){grid.replaceChildren();grid.dataset.game=game;secret.dataset.puzzle=game;secret.dataset.boards=wordCount;grid.style.gridTemplateColumns=game==='wordle'?'':game==='nonogram'?'32px repeat('+gridSize+',1fr)':'repeat('+gridSize+',1fr)';document.querySelector('#word-form').hidden=game!=='wordle';document.querySelector('#size-options').hidden=game==='wordle';document.querySelector('#word-options').hidden=game!=='wordle';grid.setAttribute('aria-label',game+' puzzle');if(game==='wordle'){targets.forEach((target,k)=>{const wrap=document.createElement('div');wrap.className='word-board';wrap.setAttribute('aria-label','Word '+(k+1));const solveAt=guesses.indexOf(target);for(let r=0;r<guessLimit;r++){const word=solveAt>=0&&r>solveAt?'':guesses[r]||'',scores=word?scoreWord(word,target):[];for(let c=0;c<5;c++){const cell=document.createElement('span');cell.className='word-cell '+(scores[c]||'');cell.textContent=word[c]||'';cell.setAttribute('aria-label',word[c]?word[c]+': '+scores[c]:'Empty letter');wrap.append(cell)}}grid.append(wrap)});document.querySelector('#word-input').disabled=won||guesses.length>=guessLimit;document.querySelector('#word-submit').disabled=won||guesses.length>=guessLimit;}else{if(game==='nonogram'){grid.append(document.createElement('span'));for(let c=0;c<gridSize;c++){const label=document.createElement('span');label.className='nonogram-clue column-clue';label.textContent=clues(picture.filter((_,i)=>i%gridSize===c));grid.append(label)}}board.forEach((v,i)=>{if(game==='nonogram'&&i%gridSize===0){const label=document.createElement('span');label.className='nonogram-clue';label.textContent=clues(picture.slice(i,i+gridSize));grid.append(label)}const btn=document.createElement('button');btn.type='button';btn.classList.toggle('on',v===true||v===1);btn.textContent=v===2?'×':'';btn.setAttribute('aria-label','Row '+(Math.floor(i/gridSize)+1)+', column '+(i%gridSize+1)+': '+(v===2?'marked empty':v?'filled':'blank'));btn.disabled=won;btn.addEventListener('click',()=>{if(game==='lights'){flip(i);won=board.every(x=>!x)}else{board[i]=(board[i]+1)%3;won=board.every((x,j)=>(x===1?1:0)===picture[j])}moves++;paintPuzzle();if(won)document.querySelector('#new-puzzle').focus();else grid.querySelectorAll('button')[i].focus()});grid.append(btn)})}document.querySelector('#move-count').textContent=game==='wordle'?guesses.length+' / '+guessLimit+' guesses · '+targets.filter(t=>guesses.includes(t)).length+'/'+wordCount+' solved':moves+' moves';document.querySelector('.secret-status').textContent=won?'Solved! Another puzzle?':game==='wordle'&&guesses.length>=guessLimit?'Answers: '+targets.join(', '):''}
function newPuzzle(){moves=0;won=false;guesses=[];board=Array(gridSize*gridSize).fill(0);if(game==='lights'){for(let i=0;i<gridSize*2;i++)flip(Math.floor(Math.random()*board.length));if(board.every(v=>!v))flip(0)}else if(game==='wordle'){const pool=[...answers];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}targets=pool.slice(0,wordCount);guessLimit=wordCount===1?6:wordCount===4?9:13;}else if(gridSize===5){picture=patterns[Math.floor(Math.random()*patterns.length)].split('').map(Number)}else{const type=Math.floor(Math.random()*3),mid=Math.floor(gridSize/2);picture=Array.from({length:gridSize*gridSize},(_,i)=>{const r=Math.floor(i/gridSize),c=i%gridSize;return +(type===0?r===0||r===gridSize-1||c===0||c===gridSize-1:type===1?r===mid||c===mid:r%2===0)})}document.querySelector('#word-input').value='';document.querySelector('#puzzle-instructions').textContent={lights:'Turn off every filled square. A click flips its neighbours too.',wordle:'One guess plays across every board. Green: right spot. Gold: wrong spot. Grey: absent.',nonogram:'Clues give filled runs separated by empty cells. Click: filled → × empty → blank.'}[game];paintPuzzle()}
document.querySelector('#grid-size').addEventListener('change',e=>{gridSize=Number(e.target.value);newPuzzle()});
document.querySelector('#word-variant').addEventListener('change',e=>{wordCount=Number(e.target.value);newPuzzle()});
document.querySelector('#word-form').addEventListener('submit',e=>{e.preventDefault();if(game!=='wordle'||won||guesses.length>=guessLimit)return;const input=document.querySelector('#word-input'),word=input.value.trim().toUpperCase();if(!/^[A-Z]{5}$/.test(word)||!dictionary.has(word)){document.querySelector('.secret-status').textContent='Enter a five-letter dictionary word.';return}guesses.push(word);won=targets.every(t=>guesses.includes(t));input.value='';paintPuzzle();if(won||guesses.length>=guessLimit)document.querySelector('#new-puzzle').focus();else input.focus()});
document.querySelectorAll('[data-game]').forEach(button=>button.addEventListener('click',()=>{game=button.dataset.game;document.querySelectorAll('[data-game]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));newPuzzle()}));
function openSecret(){if(secret.open)return;returnFocus=document.activeElement;newPuzzle();secret.showModal();document.querySelector('#secret-close').focus()}
function closeSecret(){secret.close();returnFocus?.focus()}
document.querySelector('.secret-hint').addEventListener('click',openSecret);document.querySelector('#secret-close').addEventListener('click',closeSecret);document.querySelector('#new-puzzle').addEventListener('click',newPuzzle);secret.addEventListener('cancel',()=>requestAnimationFrame(()=>returnFocus?.focus()));
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,[contenteditable="true"]')||secret.open)return;if(e.key.length===1){sequence=(sequence+e.key.toLowerCase()).slice(-5);if(sequence==='steph'){sequence='';openSecret()}}});

// Local search indexes the same content rendered by the pages.
const searchInput=document.querySelector('#search-input'),searchPanel=document.querySelector('#search-panel'),searchResults=document.querySelector('#search-results');
const plain=html=>{const el=document.createElement('div');el.innerHTML=html;return el.textContent.replace(/\s+/g,' ').trim()};
const searchIndex=[
...allProjects.map(p=>({title:p.name,category:p.group,kind:'project',url:'#projects/'+p.id,text:(p.description||'')+' '+(p.tags||'')+' '+(projectSummaries[p.id]||'')})),
...Object.entries(pages).filter(([key])=>!['projects','blog'].includes(key)).map(([key,renderPage])=>({title:{home:'Stephanie Gao',experiences:'Experiences',places:'Places',hobbies:'Outside of work'}[key],category:'Page',url:'#'+key,text:plain(renderPage())})),
...posts.map(p=>({title:p.title,category:'Writing',kind:'writing',url:'#blog/'+p.id,text:plain(p.body)}))
];
function clearSearch(){searchInput.value='';searchPanel.hidden=true;main.hidden=false;document.querySelector('#search-clear').hidden=true}
function normalizeSearch(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function findSearchResults(query){const terms=normalizeSearch(query).split(/\s+/).filter(Boolean);let kind=null;const filtered=terms.filter(t=>{if(['project','projects','apps','app'].includes(t)){kind='project';return false}if(['blog','blogs','writing','posts'].includes(t)){kind='writing';return false}return !['all','my','the'].includes(t)});return searchIndex.filter(p=>(!kind||p.kind===kind)&&filtered.every(t=>normalizeSearch(p.title+' '+p.category+' '+p.text).includes(t))).sort((a,b)=>{const q=filtered.join(' '),at=normalizeSearch(a.title),bt=normalizeSearch(b.title);return Number(bt===q)-Number(at===q)||Number(bt.startsWith(q))-Number(at.startsWith(q))||a.title.localeCompare(b.title,'en',{sensitivity:'base'})})}
function search(){const query=searchInput.value.trim();if(!query){clearSearch();return}const results=findSearchResults(query);searchPanel.hidden=false;main.hidden=true;document.querySelector('#search-clear').hidden=false;searchResults.replaceChildren();document.querySelector('#search-count').textContent=results.length?results.length+' result'+(results.length===1?'':'s'):'No results. Try projects, academic, a project name, or a topic.';for(const p of results){const li=document.createElement('li'),a=document.createElement('a'),meta=document.createElement('span');a.href=p.url;a.textContent=p.title;meta.className='meta';meta.textContent=p.kind==='project'?'Project · '+p.category:p.category;li.append(a,meta);searchResults.append(li)}}
searchInput.addEventListener('input',search);document.querySelector('#site-search').addEventListener('submit',e=>{e.preventDefault();searchResults.querySelector('a')?.focus()});document.querySelector('#search-clear').addEventListener('click',()=>{clearSearch();searchInput.focus()});searchResults.addEventListener('click',e=>{if(e.target.closest('a')){clearSearch();main.focus()}});searchInput.addEventListener('keydown',e=>{if(e.key==='Escape'){clearSearch();searchInput.blur()}if(e.key==='ArrowDown'){e.preventDefault();searchResults.querySelector('a')?.focus()}});
const themeButton=document.querySelector('#theme-toggle');
function applyTheme(theme){document.documentElement.dataset.theme=theme;themeButton.innerHTML=theme==='dark'?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 15.5A8.5 8.5 0 0 1 8.5 4 8.5 8.5 0 1 0 20 15.5Z"/></svg>' ;themeButton.setAttribute('aria-label','Switch to '+(theme==='dark'?'light':'dark')+' mode');themeButton.setAttribute('aria-pressed',String(theme==='dark'))}
applyTheme(document.documentElement.dataset.theme||'light');themeButton.addEventListener('click',()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{localStorage.setItem('portfolio-theme',theme)}catch{}});
matchMedia('(prefers-color-scheme:dark)').addEventListener('change',e=>{try{if(!localStorage.getItem('portfolio-theme'))applyTheme(e.matches?'dark':'light')}catch{}});
render();

const ownerTimezone='America/Argentina/Buenos_Aires';
const visitorTimezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
function updateClocks(){const now=new Date();for(const [id,zone,label] of [['visitor-clock',visitorTimezone,'you'],['steph-clock',ownerTimezone,'me']]){const time=new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now);const place=zone.split('/').pop().replaceAll('_',' ');const node=document.getElementById(id);node.querySelector('time').textContent=time;node.querySelector('time').dateTime=now.toISOString();node.querySelector('.clock-place').textContent=place;node.setAttribute('aria-label',label+': '+time+' in '+place)}}
updateClocks();setInterval(updateClocks,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClocks()});

