main.addEventListener('click',e=>{const opener=e.target.closest('.camera-open');if(!opener)return;const dialog=document.createElement('dialog');dialog.className='content-popup instagram-popup';dialog.setAttribute('aria-labelledby','content-popup-title');dialog.innerHTML=`<button type="button" class="content-close" aria-label="Close making content">×</button><span class="scrap-label">camera roll / @stephanie_tyc</span><h2 id="content-popup-title">Making content</h2><p>Short-form videos, makeup, and little moments I want to keep.</p><a class="instagram-preview" href="https://www.instagram.com/stephanie_tyc/" target="_blank" rel="noopener noreferrer" aria-label="Open Stephanie's Instagram profile"><span class="instagram-avatar" aria-hidden="true">s</span><span class="instagram-profile-copy"><strong>@stephanie_tyc</strong><span>Stephanie Gao</span><small>content · makeup · little moments</small></span><span class="instagram-preview-arrow" aria-hidden="true">↗</span></a><a class="instagram-profile-link" href="https://www.instagram.com/stephanie_tyc/" target="_blank" rel="noopener noreferrer">View profile on Instagram ↗</a>`;document.body.append(dialog);dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.remove();opener.focus()});dialog.showModal()});

let spotifyController=null,spotifyLoading=false,spotifyPaused=true;
function showSpotify(){let panel=document.querySelector('.spotify-panel');if(!panel){panel=document.createElement('aside');panel.className='spotify-panel';panel.setAttribute('aria-label','Spotify player');panel.innerHTML='<button type="button" class="spotify-close" aria-label="Close Spotify controls">×</button><p>Choose or skip tracks here</p><div id="spotify-mount"></div><a href="'+spotifyUrl+'" target="_blank" rel="noopener">Open playlist in Spotify ↗</a>';document.body.append(panel);panel.querySelector('button').onclick=()=>panel.hidden=true;}panel.hidden=false;return panel}
function connectSpotify(){showSpotify();if(spotifyController||spotifyLoading)return;spotifyLoading=true;window.onSpotifyIframeApiReady=api=>api.createController(document.querySelector('#spotify-mount'),{uri:'spotify:playlist:5zfpoBQbbJdg9yze5afZ5M',width:'100%',height:352},controller=>{spotifyController=controller;controller.addListener('ready',()=>{spotifyLoading=false;controller.play()});controller.addListener('playback_update',e=>{spotifyPaused=e.data.isPaused;const player=main.querySelector('.mini-turntable');if(!player)return;player.classList.toggle('needle-down',!spotifyPaused);const needle=player.querySelector('.tonearm');needle.setAttribute('aria-pressed',String(!spotifyPaused));needle.setAttribute('aria-label',spotifyPaused?'Drop needle to play':'Lift needle to pause');player.querySelector('.record-message').textContent=e.data.isBuffering?'Loading…':spotifyPaused?'Drop the needle to play.':'Playing from Spotify';});});const script=document.createElement('script');script.src='https://open.spotify.com/embed/iframe-api/v1';script.onerror=()=>{spotifyLoading=false;const mount=document.querySelector('#spotify-mount');mount.textContent='Player unavailable. Open the playlist in Spotify using the link below.';};document.head.append(script)}
main.addEventListener('click',e=>{if(e.target.closest('.record-skip')){connectSpotify();return}if(!e.target.closest('.tonearm'))return;if(!spotifyController){connectSpotify();return}if(spotifyPaused)spotifyController.resume();else spotifyController.pause();});

main.addEventListener('click',e=>{const opener=e.target.closest('.books-open');if(!opener)return;const dialog=document.createElement('dialog');dialog.className='content-popup books-popup';dialog.setAttribute('aria-labelledby','books-popup-title');dialog.innerHTML=`<button type="button" class="content-close" aria-label="Close books">×</button><span class="scrap-label">from the shelf</span><h2 id="books-popup-title">Two books</h2><div class="open-book"><div class="book-page"><span class="page-number">01 / to share</span><h3>I'd recommend</h3><p class="book-title">Tomorrow, and Tomorrow, and Tomorrow</p></div><div class="book-page"><span class="page-number">02 / on my nightstand</span><h3>Currently reading</h3><p class="book-title">A Psalm for the Wild-Built</p></div><div class="opening-cover" aria-hidden="true"></div></div>`;document.body.append(dialog);dialog.querySelector('.content-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.remove();opener.focus()});dialog.showModal()});
main.addEventListener('click',e=>{const opener=e.target.closest('.dance-open');if(!opener)return;const dialog=document.createElement('dialog');dialog.className='content-popup dance-popup';dialog.setAttribute('aria-labelledby','dance-popup-title');dialog.innerHTML='<button type="button" class="content-close" aria-label="Close dance">×</button><span class="hand-note">a little movement helps</span><h2 id="dance-popup-title">Dance breaks</h2><p>If I’m away from my desk, there’s a good chance I’m dancing.</p>';document.body.append(dialog);dialog.querySelector('button').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{dialog.remove();opener.focus()});dialog.showModal()});
